@import "tailwindcss";

@theme {
  --color-primary: #02838D;
  --color-primary-dark: #01626A;
  --color-primary-light: #E6F3F4;
  --color-primary-lighter: #F0F8F9;
  --color-accent: #F4845F;
  --color-accent-hover: #E6734A;
  --color-accent-light: #FFF0EB;
  --color-bg: #FAFAF8;
  --color-bg-secondary: #F0F4F4;
  --color-bg-warm: #F7F5F2;
  --color-text: #231F20;
  --color-text-secondary: #5D595A;
  --color-text-muted: #8E8A8B;
  --color-border: #E0DED8;
  --color-border-light: #EBE9E3;
  --color-card: #FFFFFF;
  --color-surface: #F7F3EE;
  --color-success: #2D8B6E;
  --color-amber: #F0A048;
  --font-display: 'Playfair Display', serif;
  --font-sans: 'DM Sans', sans-serif;
  --radius-card: 0.75rem;
  --radius-lg: 1rem;
  --shadow-card: 0 1px 3px rgba(35, 31, 32, 0.06), 0 1px 2px rgba(35, 31, 32, 0.04);
  --shadow-card-hover: 0 4px 12px rgba(35, 31, 32, 0.08), 0 2px 4px rgba(35, 31, 32, 0.04);
  --shadow-elevated: 0 8px 24px rgba(35, 31, 32, 0.10), 0 2px 8px rgba(35, 31, 32, 0.06);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  line-height: 1.6;
}

h1, h2, h3, h4 {
  font-family: var(--font-display);
  color: var(--color-text);
  line-height: 1.2;
}

@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes pulse-soft {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.animate-ticker {
  animation: ticker-scroll 40s linear infinite;
}

.animate-fade-in-up {
  animation: fadeInUp 0.6s ease-out forwards;
}

.animate-fade-in {
  animation: fadeIn 0.5s ease-out forwards;
}

.text-balance {
  text-wrap: balance;
}

.hide-scrollbar::-webkit-scrollbar {
  display: none;
}
.hide-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.grain-overlay::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.03'/%3E%3C/svg%3E");
  background-repeat: repeat;
  pointer-events: none;
  z-index: 9999;
}

